// Minimal Grok Bot -> jade-py bridge.
// Runs in the Grok Bot environment or as a local server.
// Expects:
//   JADE_API_URL     http://localhost:8760/v1/chat
//   JADE_API_TOKEN   generated by jade-py
//   GROK_PORT        8780 (optional)

const http = require('http');
const url = require('url');

const JADE_API_URL = process.env.JADE_API_URL || 'http://localhost:8760/v1/chat';
const JADE_API_TOKEN = process.env.JADE_API_TOKEN;
const PORT = parseInt(process.env.GROK_PORT || '8780', 10);

function forward(method, targetUrl, body, headers = {}) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(targetUrl);
    const opts = {
      hostname: parsed.hostname,
      port: parsed.port,
      path: parsed.pathname + parsed.search,
      method,
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        ...(JADE_API_TOKEN ? { 'Authorization': `Bearer ${JADE_API_TOKEN}` } : {}),
        ...headers
      }
    };
    const req = http.request(opts, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (e) {
          reject(new Error(`non-JSON response: ${data}`));
        }
      });
    });
    req.on('error', reject);
    if (body) req.write(JSON.stringify(body));
    req.end();
  });
}

const server = http.createServer(async (req, res) => {
  if (req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: true }));
    return;
  }

  if (req.url !== '/v1' && req.url !== '/v1/chat') {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: false, error: 'unknown endpoint' }));
    return;
  }

  if (req.method !== 'POST') {
    res.writeHead(405, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: false, error: 'METHOD_NOT_ALLOWED' }));
    return;
  }

  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', async () => {
    try {
      const payload = JSON.parse(body);
      const message = payload.message || payload.prompt || payload.text || '';
      if (!message) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: false, error: 'missing_message' }));
        return;
      }
      const result = await forward('POST', JADE_API_URL, { message, stream: false });
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    } catch (err) {
      res.writeHead(502, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: false, error: err.message }));
    }
  });
});

server.listen(PORT, () => {
  console.log(`Grok bridge listening on port ${PORT}`);
});
